'use client'
import React, { useState, useEffect } from 'react'
import { Howler } from 'howler'
import gsap from 'gsap'
import { ColdBootProps } from '@/lib/types'
import { playMenuSelect } from '@/lib/sounds'

export default function ColdBoot({ onComplete }: ColdBootProps) {
    const [started, setStarted] = useState<boolean>(false)
    const containerRef = React.useRef<HTMLDivElement | null>(null)
    const textRef = React.useRef<HTMLDivElement | null>(null)

    const handleStart = async () => {
        if (started) return
        setStarted(true)

        try {
            if (Howler && Howler.ctx && Howler.ctx.state !== 'running') {
                await Howler.ctx.resume()
            }
            playMenuSelect()
        } catch (err) {
            console.warn('Audio resume notice:', err)
        }

        if (textRef.current) {
            gsap.to(textRef.current, {
                scale: 1.1,
                opacity: 0,
                filter: 'blur(8px)',
                duration: 0.5,
                ease: 'power2.in',
            })
        }

        // Brief cinematic pause before handing off to WantedStars
        setTimeout(() => {
            onComplete()
        }, 600)
    }

    useEffect(() => {
        const handleKeyDown = () => {
            handleStart()
        }
        window.addEventListener('keydown', handleKeyDown)
        return () => window.removeEventListener('keydown', handleKeyDown)
    }, [started])

    return (
        <div
            ref={containerRef}
            onClick={!started ? handleStart : undefined}
            style={{
                position: 'fixed',
                inset: 0,
                background: 'radial-gradient(ellipse at center, #0e0e12 0%, #050507 100%)',
                zIndex: 100,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                cursor: !started ? 'pointer' : 'default',
                userSelect: 'none',
            }}
        >
            <div className="heavy-vignette" />

            {!started && (
                <div
                    ref={textRef}
                    style={{
                        textAlign: 'center',
                        zIndex: 110,
                        padding: '36px',
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        gap: '22px',
                        maxWidth: '720px',
                    }}
                >
                    {/* Rockstar-style Top Tagline */}
                    <div
                        style={{
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: '10px',
                            background: 'rgba(245, 166, 35, 0.08)',
                            border: '1px solid rgba(245, 166, 35, 0.35)',
                            padding: '4px 16px',
                        }}
                    >
                        <div
                            style={{
                                width: '6px',
                                height: '6px',
                                background: '#f5a623',
                                boxShadow: '0 0 6px #f5a623',
                            }}
                        />
                        <span
                            style={{
                                fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                                fontSize: 'clamp(0.75rem, 1.6vw, 0.9rem)',
                                letterSpacing: '0.35em',
                                color: '#f5a623',
                                textTransform: 'uppercase',
                                fontWeight: 700,
                            }}
                        >
                            OM PANDEY // LOS SANTOS PROTOCOL
                        </span>
                    </div>

                    <h1
                        style={{
                            fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                            fontSize: 'clamp(1.8rem, 4.5vw, 3rem)',
                            letterSpacing: '0.12em',
                            color: '#ffffff',
                            textTransform: 'uppercase',
                            margin: 0,
                            lineHeight: 1.05,
                            textShadow: '0 4px 20px rgba(0, 0, 0, 0.9)',
                        }}
                    >
                        INTERACTIVE DEVELOPER PORTFOLIO
                    </h1>

                    <p
                        className="smooth-pulse"
                        style={{
                            fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                            fontSize: 'clamp(0.85rem, 1.8vw, 1.1rem)',
                            letterSpacing: '0.3em',
                            color: 'rgba(255, 255, 255, 0.75)',
                            textTransform: 'uppercase',
                            margin: 0,
                        }}
                    >
                        CLICK ANYWHERE OR PRESS ANY KEY TO INITIALIZE
                    </p>

                    <div
                        style={{
                            width: '48px',
                            height: '2px',
                            background: '#f5a623',
                            marginTop: '6px',
                            boxShadow: '0 0 12px rgba(245, 166, 35, 0.9)',
                        }}
                    />
                </div>
            )}
        </div>
    )
}
